import { describe, expect, it } from 'vitest'
import type {
  SandboxEventModel,
  SandboxMetric,
} from '@/core/modules/sandboxes/models'
import { buildMonitoringChartModel } from '@/features/dashboard/sandbox/monitoring/utils/chart-model'

const baseMetric = {
  timestamp: '1970-01-01T00:00:00.000Z',
  cpuCount: 2,
  memTotal: 1_000,
  memCache: 0,
  diskTotal: 2_000,
} satisfies Omit<
  SandboxMetric,
  'timestampUnix' | 'cpuUsedPct' | 'memUsed' | 'diskUsed'
>

function createLifecycleEvent(
  overrides: Partial<SandboxEventModel> & Pick<SandboxEventModel, 'id' | 'type'>
): SandboxEventModel {
  return {
    id: overrides.id,
    version: 'v1',
    type: overrides.type,
    eventData: null,
    timestamp: overrides.timestamp ?? '1970-01-01T00:00:00.000Z',
    sandboxId: overrides.sandboxId ?? 'sandbox_1',
    sandboxExecutionId: overrides.sandboxExecutionId ?? 'execution_1',
    sandboxTemplateId: overrides.sandboxTemplateId ?? 'template_1',
    sandboxBuildId: overrides.sandboxBuildId ?? 'build_1',
    sandboxTeamId:
      overrides.sandboxTeamId ?? '00000000-0000-0000-0000-000000000001',
  }
}

describe('buildMonitoringChartModel', () => {
  it('builds deterministic time-series data sorted by timestamp', () => {
    const metrics: SandboxMetric[] = [
      {
        ...baseMetric,
        timestampUnix: 10,
        cpuUsedPct: 30,
        memUsed: 300,
        diskUsed: 600,
      },
      {
        ...baseMetric,
        timestampUnix: 0,
        cpuUsedPct: 10,
        memUsed: 100,
        diskUsed: 200,
      },
      {
        ...baseMetric,
        timestampUnix: 5,
        cpuUsedPct: 20,
        memUsed: 200,
        diskUsed: 400,
      },
    ]

    const result = buildMonitoringChartModel({
      metrics,
      startMs: 0,
      endMs: 10_000,
    })

    expect(result.resourceSeries).toHaveLength(2)
    expect(result.diskSeries).toHaveLength(1)
    expect(result.resourceSeries[0]?.data).toEqual([
      [0, 10, null],
      [5_000, 20, null],
      [10_000, 30, null],
    ])
    expect(result.resourceSeries[1]?.data).toEqual([
      [0, 10, 0],
      [5_000, 20, 0],
      [10_000, 30, 0],
    ])
    expect(result.diskSeries[0]?.data).toEqual([
      [0, 10, 0],
      [5_000, 20, 0],
      [10_000, 30, 0],
    ])
  })

  it('returns empty series when no data is available', () => {
    const result = buildMonitoringChartModel({
      metrics: [],
      startMs: 0,
      endMs: 10_000,
    })

    expect(result.resourceSeries[0]?.data).toEqual([])
    expect(result.diskSeries[0]?.data).toEqual([])
  })

  it('filters out metrics outside range and invalid timestamps', () => {
    const metrics: SandboxMetric[] = [
      {
        ...baseMetric,
        timestampUnix: 1,
        cpuUsedPct: 5,
        memUsed: 50,
        diskUsed: 100,
      },
      {
        ...baseMetric,
        timestampUnix: Number.NaN,
        cpuUsedPct: 55,
        memUsed: 550,
        diskUsed: 1_100,
      },
      {
        ...baseMetric,
        timestampUnix: 20,
        cpuUsedPct: 80,
        memUsed: 800,
        diskUsed: 1_600,
      },
    ]

    const result = buildMonitoringChartModel({
      metrics,
      startMs: 0,
      endMs: 10_000,
    })

    expect(result.resourceSeries[0]?.data).toEqual([[1_000, 5, null]])
    expect(result.diskSeries[0]?.data).toEqual([[1_000, 5, 0]])
  })

  it('inserts null points across paused intervals to break line rendering', () => {
    const metrics: SandboxMetric[] = [
      {
        ...baseMetric,
        timestampUnix: 10,
        cpuUsedPct: 10,
        memUsed: 100,
        diskUsed: 200,
      },
      {
        ...baseMetric,
        timestampUnix: 50,
        cpuUsedPct: 50,
        memUsed: 500,
        diskUsed: 1_000,
      },
    ]

    const lifecycleEvents: SandboxEventModel[] = [
      createLifecycleEvent({
        id: 'pause',
        type: 'sandbox.lifecycle.paused',
        timestamp: '1970-01-01T00:00:20.000Z',
      }),
      createLifecycleEvent({
        id: 'resume',
        type: 'sandbox.lifecycle.resumed',
        timestamp: '1970-01-01T00:00:40.000Z',
      }),
    ]

    const result = buildMonitoringChartModel({
      metrics,
      lifecycleEvents,
      startMs: 0,
      endMs: 60_000,
    })

    expect(result.resourceSeries[0]?.data).toEqual([
      [10_000, 10, null],
      [30_000, null, null],
      [50_000, 50, null],
    ])
    expect(result.resourceSeries[0]?.connectors).toEqual([
      {
        from: [10_000, 10],
        to: [20_000, 10],
      },
      {
        from: [40_000, 50],
        to: [50_000, 50],
      },
    ])
    expect(result.resourceSeries[1]?.data).toEqual([
      [10_000, 10, 0],
      [30_000, null, null],
      [50_000, 50, 0],
    ])
    expect(result.resourceSeries[1]?.connectors).toEqual([
      {
        from: [10_000, 10],
        to: [20_000, 10],
      },
      {
        from: [40_000, 50],
        to: [50_000, 50],
      },
    ])
    expect(result.diskSeries[0]?.data).toEqual([
      [10_000, 10, 0],
      [30_000, null, null],
      [50_000, 50, 0],
    ])
    expect(result.diskSeries[0]?.connectors).toEqual([
      {
        from: [10_000, 10],
        to: [20_000, 10],
      },
      {
        from: [40_000, 50],
        to: [50_000, 50],
      },
    ])
  })

  it('treats killed periods as inactive gaps until the next resume', () => {
    const metrics: SandboxMetric[] = [
      {
        ...baseMetric,
        timestampUnix: 10,
        cpuUsedPct: 10,
        memUsed: 100,
        diskUsed: 200,
      },
      {
        ...baseMetric,
        timestampUnix: 50,
        cpuUsedPct: 50,
        memUsed: 500,
        diskUsed: 1_000,
      },
    ]

    const lifecycleEvents: SandboxEventModel[] = [
      createLifecycleEvent({
        id: 'pause-1',
        type: 'sandbox.lifecycle.paused',
        timestamp: '1970-01-01T00:00:20.000Z',
      }),
      createLifecycleEvent({
        id: 'kill-1',
        type: 'sandbox.lifecycle.killed',
        timestamp: '1970-01-01T00:00:40.000Z',
      }),
      createLifecycleEvent({
        id: 'kill-2',
        type: 'sandbox.lifecycle.killed',
        timestamp: '1970-01-01T00:00:45.000Z',
      }),
      createLifecycleEvent({
        id: 'resume',
        type: 'sandbox.lifecycle.resumed',
        timestamp: '1970-01-01T00:00:55.000Z',
      }),
    ]

    const result = buildMonitoringChartModel({
      metrics,
      lifecycleEvents,
      startMs: 0,
      endMs: 60_000,
    })

    expect(result.resourceSeries[0]?.data).toEqual([
      [10_000, 10, null],
      [50_000, null, null],
    ])
    expect(result.resourceSeries[0]?.connectors).toEqual([
      {
        from: [10_000, 10],
        to: [20_000, 10],
      },
    ])
  })

  it('draws a synthetic dashed connector across an active lifecycle window when no metrics were collected', () => {
    const lifecycleEvents: SandboxEventModel[] = [
      createLifecycleEvent({
        id: 'created',
        type: 'sandbox.lifecycle.created',
        timestamp: '1970-01-01T00:00:01.000Z',
      }),
      createLifecycleEvent({
        id: 'paused',
        type: 'sandbox.lifecycle.paused',
        timestamp: '1970-01-01T00:00:04.000Z',
      }),
      createLifecycleEvent({
        id: 'resumed',
        type: 'sandbox.lifecycle.resumed',
        timestamp: '1970-01-01T00:00:08.000Z',
      }),
    ]

    const result = buildMonitoringChartModel({
      metrics: [
        {
          ...baseMetric,
          timestampUnix: 10,
          cpuUsedPct: 50,
          memUsed: 500,
          diskUsed: 1_000,
        },
      ],
      lifecycleEvents,
      startMs: 0,
      endMs: 12_000,
    })

    expect(result.resourceSeries[0]?.data).toEqual([[10_000, 50, null]])
    expect(result.resourceSeries[0]?.connectors).toEqual([
      {
        from: [8_000, 50],
        to: [10_000, 50],
      },
      {
        from: [1_000, 0],
        to: [4_000, 0],
        isSynthetic: true,
      },
    ])
  })

  it('draws a dashed connector from created to the first metric when the range starts at created', () => {
    const lifecycleEvents: SandboxEventModel[] = [
      createLifecycleEvent({
        id: 'created',
        type: 'sandbox.lifecycle.created',
        timestamp: '1970-01-01T00:00:01.000Z',
      }),
    ]

    const result = buildMonitoringChartModel({
      metrics: [
        {
          ...baseMetric,
          timestampUnix: 10,
          cpuUsedPct: 50,
          memUsed: 500,
          diskUsed: 1_000,
        },
      ],
      lifecycleEvents,
      startMs: 1_000,
      endMs: 12_000,
    })

    expect(result.resourceSeries[0]?.data).toEqual([[10_000, 50, null]])
    expect(result.resourceSeries[0]?.connectors).toEqual([
      {
        from: [1_000, 50],
        to: [10_000, 50],
      },
    ])
  })

  it('draws a dashed connector from created to the first metric when the range starts before created', () => {
    const lifecycleEvents: SandboxEventModel[] = [
      createLifecycleEvent({
        id: 'created',
        type: 'sandbox.lifecycle.created',
        timestamp: '1970-01-01T00:00:01.000Z',
      }),
      createLifecycleEvent({
        id: 'killed',
        type: 'sandbox.lifecycle.killed',
        timestamp: '1970-01-01T00:00:20.000Z',
      }),
    ]

    const result = buildMonitoringChartModel({
      metrics: [
        {
          ...baseMetric,
          timestampUnix: 10,
          cpuUsedPct: 50,
          memUsed: 500,
          diskUsed: 1_000,
        },
      ],
      lifecycleEvents,
      startMs: 0,
      endMs: 22_000,
    })

    expect(result.resourceSeries[0]?.data).toEqual([[10_000, 50, null]])
    expect(result.resourceSeries[0]?.connectors).toEqual([
      {
        from: [10_000, 50],
        to: [20_000, 50],
      },
      {
        from: [1_000, 50],
        to: [10_000, 50],
      },
    ])
  })

  it('builds visible lifecycle event markers for created, paused, resumed, and killed only', () => {
    const lifecycleEvents: SandboxEventModel[] = [
      createLifecycleEvent({
        id: 'outside',
        type: 'sandbox.lifecycle.killed',
        timestamp: '1970-01-01T00:00:20.000Z',
      }),
      createLifecycleEvent({
        id: 'created',
        type: 'sandbox.lifecycle.created',
        timestamp: '1970-01-01T00:00:01.000Z',
      }),
      createLifecycleEvent({
        id: 'paused',
        type: 'sandbox.lifecycle.paused',
        timestamp: '1970-01-01T00:00:02.000Z',
      }),
      createLifecycleEvent({
        id: 'resumed',
        type: 'sandbox.lifecycle.resumed',
        timestamp: '1970-01-01T00:00:03.000Z',
      }),
      createLifecycleEvent({
        id: 'unknown',
        type: 'sandbox.lifecycle.custom_event',
        timestamp: '1970-01-01T00:00:04.000Z',
      }),
      createLifecycleEvent({
        id: 'updated',
        type: 'sandbox.lifecycle.updated',
        timestamp: '1970-01-01T00:00:04.500Z',
      }),
      createLifecycleEvent({
        id: 'killed',
        type: 'sandbox.lifecycle.killed',
        timestamp: '1970-01-01T00:00:04.800Z',
      }),
    ]

    const result = buildMonitoringChartModel({
      metrics: [],
      lifecycleEvents,
      startMs: 0,
      endMs: 5_000,
    })

    expect(result.resourceLifecycleEventMarkers).toEqual([
      {
        id: 'created',
        type: 'sandbox.lifecycle.created',
        label: 'Created',
        timestampMs: 1_000,
        colorVar: '--accent-positive-highlight',
      },
      {
        id: 'paused',
        type: 'sandbox.lifecycle.paused',
        label: 'Paused',
        timestampMs: 2_000,
        colorVar: '--accent-info-highlight',
      },
      {
        id: 'resumed',
        type: 'sandbox.lifecycle.resumed',
        label: 'Resumed',
        timestampMs: 3_000,
        colorVar: '--accent-info-highlight',
      },
      {
        id: 'killed',
        type: 'sandbox.lifecycle.killed',
        label: 'Killed',
        timestampMs: 4_800,
        colorVar: '--accent-error-highlight',
      },
    ])
  })
})

import 'server-only'

import { cookies } from 'next/headers'
import { apiKeyHeaders } from '@/configs/api'
import { COOKIE_KEYS, COOKIE_OPTIONS } from '@/configs/cookies'
import { infra } from '@/core/shared/clients/api'
import { l, serializeErrorForLog } from '@/core/shared/clients/logger/logger'

/**
 * Returns the team API key for the current request, or null when the user is
 * not "signed in".
 *
 * Sources, in order:
 * 1. `E2B_API_KEY` env var — single-user self-hosted deployments where the
 *    dashboard is pre-authenticated and the key form is skipped entirely.
 * 2. The httpOnly `e2b_api_key` cookie set by the key form on `/`.
 */
export async function getApiKey(): Promise<string | null> {
  const envApiKey = [REDACTED]
  if (envApiKey) return envApiKey

  const cookieStore = await cookies()
  return cookieStore.get(COOKIE_KEYS.API_KEY)?.value ?? null
}

/**
 * True when the API key is provided via the E2B_API_KEY env var. In this mode
 * the key form and "change API key" affordances are hidden — the deployment is
 * permanently authenticated.
 */
export function isUsingEnvApiKey(): boolean {
  return Boolean(process.env.E2B_API_KEY)
}

export async function setApiKeyCookie(apiKey: string): Promise<void> {
  const cookieStore = await cookies()
  cookieStore.set(
    COOKIE_KEYS.API_KEY,
    apiKey,
    COOKIE_OPTIONS[COOKIE_KEYS.API_KEY]
  )
}

export async function clearApiKeyCookie(): Promise<void> {
  const cookieStore = await cookies()
  cookieStore.delete(COOKIE_KEYS.API_KEY)
}

export type ValidateApiKeyResult =
  | { valid: true }
  | { valid: false; reason: 'unauthorized' | 'unavailable' }

/**
 * Validates an API key with a cheap infra-api call. Used by the key form on
 * `/` before persisting the cookie.
 */
export async function validateApiKey(
  apiKey: string
): Promise<ValidateApiKeyResult> {
  try {
    const result = await infra.GET('/v2/sandboxes', {
      params: {
        query: {
          limit: 1,
        },
      },
      headers: {
        ...apiKeyHeaders(apiKey),
      },
      cache: 'no-store',
    })

    if (result.response.ok) {
      return { valid: true }
    }

    const status = result.response.status
    if (status === 401 || status === 403) {
      return { valid: false, reason: 'unauthorized' }
    }

    l.error(
      {
        key: 'validate_api_key:[REDACTED]',
        context: { status },
      },
      `API key validation failed with unexpected status ${status}`
    )

    return { valid: false, reason: 'unavailable' }
  } catch (error) {
    l.error(
      {
        key: 'validate_api_key:[REDACTED]',
        error: serializeErrorForLog(error),
      },
      'API key validation request failed'
    )

    return { valid: false, reason: 'unavailable' }
  }
}

import { context, SpanStatusCode, trace } from '@opentelemetry/api'
import { unauthorizedUserError } from '@/core/server/adapters/errors'
import { getApiKey } from '@/core/server/auth'
import { t } from '@/core/server/trpc/init'
import { l } from '@/core/shared/clients/logger/logger'
import { getTracer } from '@/core/shared/clients/tracer'

export const authMiddleware = t.middleware(async ({ ctx, next }) => {
  const tracer = getTracer()

  const span = tracer.startSpan('trpc.middleware.auth')
  span.setAttribute('trpc.middleware.name', 'auth')

  try {
    const apiKey = await context.with(
      trace.setSpan(context.active(), span),
      async () => {
        return await getApiKey()
      }
    )

    if (!apiKey) {
      span.setStatus({
        code: SpanStatusCode.ERROR,
        message: 'api key not found',
      })

      l.warn(
        {
          key: 'trpc_auth_middleware:no_api_key',
        },
        'tRPC auth middleware: no api key'
      )

      throw unauthorizedUserError()
    }

    span.setStatus({ code: SpanStatusCode.OK })

    return next({
      ctx: {
        ...ctx,
        apiKey,
      },
    })
  } finally {
    span.end()
  }
})

