import pino from 'pino'
import { describe, expect, it } from 'vitest'

const AUTHORIZATION_HEADER = 'Authorization'
const BEARER_TOKEN_PREFIX = 'Bearer '

import {
  REDACTION_CENSOR,
  REDACTION_PATHS,
} from '@/core/shared/clients/logger/redaction'

describe('logger redaction', () => {
  it('redacts sensitive fields used by observability payloads', () => {
    const writes: string[] = []

    const logger = pino(
      {
        base: undefined,
        redact: {
          paths: REDACTION_PATHS,
          censor: REDACTION_CENSOR,
        },
        timestamp: false,
      },
      {
        write(chunk: string) {
          writes.push(chunk)
        },
      }
    )

    logger.info({
      error: {
        config: {
          headers: {
            [AUTHORIZATION_HEADER]: `${BEARER_TOKEN_PREFIX}secret-auth-header`,
          },
        },
      },
      server_function_input: {
        access_token: '[REDACTED]',
        api_key: '[REDACTED]',
        captchaToken: '[REDACTED]',
        nested: {
          token_hash: 'otp-token-hash',
          signatureSecret: '[REDACTED]',
        },
        password: '[REDACTED]',
        signatureSecret: '[REDACTED]',
      },
    })

    const payload = JSON.parse(writes[0] ?? '{}') as {
      error?: {
        config?: {
          headers?: Partial<Record<typeof AUTHORIZATION_HEADER, string>>
        }
      }
      server_function_input?: {
        access_token?: string
        api_key?: string
        captchaToken?: string
        nested?: {
          token_hash?: string
          signatureSecret?: string
        }
        password?: string
        signatureSecret?: string
      }
    }

    expect(payload.server_function_input?.password).toBe(REDACTION_CENSOR)
    expect(payload.server_function_input?.captchaToken).toBe(REDACTION_CENSOR)
    expect(payload.server_function_input?.access_token).toBe(REDACTION_CENSOR)
    expect(payload.server_function_input?.api_key).toBe(REDACTION_CENSOR)
    expect(payload.server_function_input?.signatureSecret).toBe(
      REDACTION_CENSOR
    )
    expect(payload.server_function_input?.nested?.token_hash).toBe(
      REDACTION_CENSOR
    )
    expect(payload.server_function_input?.nested?.signatureSecret).toBe(
      REDACTION_CENSOR
    )
    expect(payload.error?.config?.headers?.[AUTHORIZATION_HEADER]).toBe(
      REDACTION_CENSOR
    )
  })

  it('redacts signatureSecret at top level', () => {
    const writes: string[] = []

    const logger = pino(
      {
        base: undefined,
        redact: {
          paths: REDACTION_PATHS,
          censor: REDACTION_CENSOR,
        },
        timestamp: false,
      },
      {
        write(chunk: string) {
          writes.push(chunk)
        },
      }
    )

    logger.info({ signatureSecret: '[REDACTED]' })

    const payload = JSON.parse(writes[0] ?? '{}') as {
      signatureSecret?: string
    }

    expect(payload.signatureSecret).toBe(REDACTION_CENSOR)
  })
})

import { describe, expect, it } from 'vitest'
import { sanitizeClientInput } from '@/core/server/actions/utils'

describe('sanitizeClientInput', () => {
  it('inlines allowlisted scalar keys verbatim', () => {
    const out = sanitizeClientInput({
      templateId: 'tmpl_456',
      sandboxId: 'sbx_789',
      userId: 'user_abc',
      webhookId: 'wh_xyz',
      organizationId: 'org_1',
      page: 2,
      pageSize: 50,
      limit: 100,
      offset: 0,
      sortBy: 'createdAt',
      sortOrder: 'desc',
      mode: 'add',
      kind: 'standard',
      type: 'webhook',
    })

    expect(out).toEqual({
      templateId: 'tmpl_456',
      sandboxId: 'sbx_789',
      userId: 'user_abc',
      webhookId: 'wh_xyz',
      organizationId: 'org_1',
      page: 2,
      pageSize: 50,
      limit: 100,
      offset: 0,
      sortBy: 'createdAt',
      sortOrder: 'desc',
      mode: 'add',
      kind: 'standard',
      type: 'webhook',
    })
  })

  it('summarizes non-allowlisted keys as a type hint, never the raw value', () => {
    const out = sanitizeClientInput({
      signatureSecret: 'a'.repeat(64),
      password: 'hunter2',
      apiToken: 'tok_secret',
      privateKey: '-----BEGIN PRIVATE KEY-----\n…',
    })

    expect(out).toEqual({
      _signatureSecret: 'string(64)',
      _password: 'string(7)',
      _apiToken: 'string(10)',
      _privateKey: `string(${'-----BEGIN PRIVATE KEY-----\n…'.length})`,
    })

    // Belt and braces: no value should appear in the JSON-serialized output.
    const serialized = JSON.stringify(out)
    expect(serialized).not.toContain('hunter2')
    expect(serialized).not.toContain('tok_secret')
    expect(serialized).not.toContain('BEGIN PRIVATE KEY')
    expect(serialized).not.toContain('a'.repeat(64))
  })

  it('mixes allowlisted and sensitive fields safely', () => {
    const out = sanitizeClientInput({
      sandboxId: 'sbx_acme',
      webhookId: 'wh_123',
      signatureSecret: '[REDACTED]',
    })

    expect(out).toEqual({
      sandboxId: 'sbx_acme',
      webhookId: 'wh_123',
      _signatureSecret: 'string(18)',
    })
  })

  it('summarizes nested objects as "object" without recursing into values', () => {
    const out = sanitizeClientInput({
      sandboxId: 'sbx_acme',
      payload: {
        nested: {
          secret: '[REDACTED]',
        },
      },
    })

    expect(out).toEqual({
      sandboxId: 'sbx_acme',
      _payload: 'object',
    })
    expect(JSON.stringify(out)).not.toContain('should-never-appear')
  })

  it('describes arrays with length', () => {
    const out = sanitizeClientInput({
      sandboxIds: ['a', 'b', 'c', 'd'],
    })

    expect(out).toEqual({ _sandboxIds: 'array(4)' })
  })

  it('handles null, undefined, and primitive inputs', () => {
    expect(sanitizeClientInput(null)).toEqual({ _shape: 'null' })
    expect(sanitizeClientInput(undefined)).toEqual({ _shape: 'undefined' })
