class MockNormalModuleReplacementPlugin {
  readonly pattern: RegExp
  readonly callback: (resource: { request: string }) => void

  constructor(
    pattern: RegExp,
    callback: (resource: { request: string }) => void
  ) {
    this.pattern = pattern
    this.callback = callback
  }
}

const resolveNextConfig = async () => nextConfig

describe('E2B browser module stubs', () => {
  it('aliases node built-ins after webpack strips node: scheme requests', async () => {
    const resolved = await resolveNextConfig()
    const webpackConfig = {
      resolve: { alias: {} as Record<string, string> },
      plugins: [] as MockNormalModuleReplacementPlugin[],
    }

    resolved.webpack?.(webpackConfig, {
      isServer: false,
      webpack: {
        NormalModuleReplacementPlugin: MockNormalModuleReplacementPlugin,
      },
    })

    expect(webpackConfig.resolve.alias).toMatchObject({
      crypto: expect.stringContaining('stubs/crypto.ts'),
      fs: expect.stringContaining('stubs/fs.ts'),
      'fs/promises': expect.stringContaining('stubs/fs-promises.ts'),
      path: expect.stringContaining('stubs/path.ts'),
      'node:crypto': expect.stringContaining('stubs/crypto.ts'),
      'node:fs': expect.stringContaining('stubs/fs.ts'),
      'node:fs/promises': expect.stringContaining('stubs/fs-promises.ts'),
      'node:path': expect.stringContaining('stubs/path.ts'),
    })

    const plugin = webpackConfig.plugins.find((plugin) =>
      plugin.pattern.test('node:fs/promises')
    )
    expect(plugin).toBeDefined()

    const resource = { request: 'node:fs/promises' }
    plugin?.callback(resource)

    expect(resource.request).toBe('fs/promises')
    expect(webpackConfig.resolve.alias[resource.request]).toContain(
      'stubs/fs-promises.ts'
    )
  })

  it('does not rewrite server webpack builds', async () => {
    const resolved = await resolveNextConfig()
    const webpackConfig = {
      resolve: { alias: {} as Record<string, string> },
      plugins: [] as MockNormalModuleReplacementPlugin[],
    }

    resolved.webpack?.(webpackConfig, {
      isServer: true,
      webpack: {
        NormalModuleReplacementPlugin: MockNormalModuleReplacementPlugin,
      },
    })

    expect(webpackConfig.resolve.alias).toEqual({})
    expect(webpackConfig.plugins).toEqual([])
  })
})

import type {
  SandboxEventModel,
  SandboxMetric,
} from '@/core/modules/sandboxes/models'
import type { MonitoringChartModel } from '../types/sandbox-metrics-chart'
import {
  applyPauseWindows,
  buildInactiveWindows,
  buildLifecycleEventMarkers,
} from './chart-lifecycle'
import {
  buildDiskSeries,
  buildResourceSeries,
  type NormalizedSandboxMetric,
  normalizeMetric,
  sortMetricsByTimestamp,
} from './chart-metrics'

interface BuildMonitoringChartModelOptions {
  metrics: SandboxMetric[]
  lifecycleEvents?: SandboxEventModel[]
  startMs: number
  endMs: number
}

export function buildMonitoringChartModel({
  metrics,
  lifecycleEvents = [],
  startMs,
  endMs,
}: BuildMonitoringChartModelOptions): MonitoringChartModel {
  const rangeStart = Math.min(startMs, endMs)
  const rangeEnd = Math.max(startMs, endMs)

  const normalizedMetrics = sortMetricsByTimestamp(
    metrics
      .map(normalizeMetric)
      .filter((metric): metric is NormalizedSandboxMetric => {
        if (!metric) {
          return false
        }

        return (
          metric.timestampMs >= rangeStart && metric.timestampMs <= rangeEnd
        )
      })
  )

  const pauseWindows = buildInactiveWindows(
    lifecycleEvents,
    rangeStart,
    rangeEnd
  )
  const resourceLifecycleEventMarkers = buildLifecycleEventMarkers(
    lifecycleEvents,
    rangeStart,
    rangeEnd
  )
  const resourceSeries = applyPauseWindows(
    buildResourceSeries(normalizedMetrics),
    pauseWindows,
    lifecycleEvents,
    rangeStart,
    rangeEnd
  )
  const diskSeries = applyPauseWindows(
    buildDiskSeries(normalizedMetrics),
    pauseWindows,
    lifecycleEvents,
    rangeStart,
    rangeEnd
  )
  return {
    resourceSeries,
    diskSeries,
    resourceLifecycleEventMarkers,
  }
}

