import { describe, expect, it } from 'vitest'
import {
  SANDBOX_MONITORING_DEFAULT_RANGE_MS,
  SANDBOX_MONITORING_MAX_RANGE_MS,
  SANDBOX_MONITORING_MIN_RANGE_MS,
} from '@/features/dashboard/sandbox/monitoring/utils/constants'
import {
  getSandboxLifecycleBounds,
  normalizeMonitoringTimeframe,
  parseMonitoringQueryState,
} from '@/features/dashboard/sandbox/monitoring/utils/timeframe'

describe('sandbox-monitoring-timeframe', () => {
  describe('normalizeMonitoringTimeframe', () => {
    it('should fallback to default range when inputs are invalid', () => {
      const now = 1_700_000_000_000

      const result = normalizeMonitoringTimeframe({
        start: Number.NaN,
        end: Number.POSITIVE_INFINITY,
        now,
      })

      expect(result.end).toBe(now)
      expect(result.start).toBe(now - SANDBOX_MONITORING_DEFAULT_RANGE_MS)
    })

    it('should enforce minimum range', () => {
      const now = 1_700_000_000_000

      const result = normalizeMonitoringTimeframe({
        start: now - 1_000,
        end: now,
        now,
      })

      expect(result.end - result.start).toBe(SANDBOX_MONITORING_MIN_RANGE_MS)
    })

    it('should cap maximum range', () => {
      const now = 1_700_000_000_000

      const result = normalizeMonitoringTimeframe({
        start: now - 365 * 24 * 60 * 60 * 1_000,
        end: now,
        now,
      })

      expect(result.end - result.start).toBe(SANDBOX_MONITORING_MAX_RANGE_MS)
    })

    it('should clamp future timestamps to now', () => {
      const now = 1_700_000_000_000

      const result = normalizeMonitoringTimeframe({
        start: now + 5_000,
        end: now + 10_000,
        now,
      })

      expect(result.end).toBe(now)
      expect(result.start).toBe(now - SANDBOX_MONITORING_MIN_RANGE_MS)
    })
  })

  describe('parseMonitoringQueryState', () => {
    it('should parse canonical query params', () => {
      const result = parseMonitoringQueryState({
        start: '1000',
        end: '2000',
      })

      expect(result).toEqual({
        start: 1000,
        end: 2000,
      })
    })

    it('should reject invalid timestamps', () => {
      const result = parseMonitoringQueryState({
        start: '123abc',
        end: String(Number.MAX_SAFE_INTEGER),
      })

      expect(result).toEqual({
        start: null,
        end: null,
      })
    })
  })

  describe('getSandboxLifecycleBounds', () => {
    it('should use pausedAt for paused sandbox anchor end', () => {
      const now = 1_700_000_000_000
      const pausedAt = now - 30_000
      const sandboxLifecycle = {
        createdAt: new Date(now - 60_000).toISOString(),
        pausedAt: new Date(pausedAt).toISOString(),
        endedAt: null,
        state: 'paused' as const,
      }

      const bounds = getSandboxLifecycleBounds(sandboxLifecycle, now)

      expect(bounds?.startMs).toBe(now - 60_000)
      expect(bounds?.anchorEndMs).toBe(pausedAt)
      expect(bounds?.isRunning).toBe(false)
    })

    it('should fall back to now for running sandbox without endAt', () => {
      const now = 1_700_000_000_000
      const sandboxLifecycle = {
        createdAt: new Date(now - 60_000).toISOString(),
        pausedAt: null,
        endedAt: null,
        state: 'running' as const,
      }

      const bounds = getSandboxLifecycleBounds(sandboxLifecycle, now)

      expect(bounds?.startMs).toBe(now - 60_000)
      expect(bounds?.anchorEndMs).toBe(now)
      expect(bounds?.isRunning).toBe(true)
    })

    it('should use endedAt for killed sandbox', () => {
      const now = 1_700_000_000_000
      const endedAt = now - 30_000
      const sandboxLifecycle = {
        createdAt: new Date(now - 60_000).toISOString(),
        pausedAt: null,
        endedAt: new Date(endedAt).toISOString(),
        state: 'killed' as const,
      }

      const bounds = getSandboxLifecycleBounds(sandboxLifecycle, now)

      expect(bounds?.startMs).toBe(now - 60_000)
      expect(bounds?.anchorEndMs).toBe(endedAt)
      expect(bounds?.isRunning).toBe(false)
    })

    it('should fall back to now for paused sandbox without pausedAt', () => {
      const now = 1_700_000_000_000
      const sandboxLifecycle = {
        createdAt: new Date(now - 60_000).toISOString(),
        pausedAt: null,
        endedAt: null,
        state: 'paused' as const,
      }

      const bounds = getSandboxLifecycleBounds(sandboxLifecycle, now)

      expect(bounds?.startMs).toBe(now - 60_000)
      expect(bounds?.anchorEndMs).toBe(now)
      expect(bounds?.isRunning).toBe(false)
    })
  })
})

'use server'

import { redirect } from 'next/navigation'
import { z } from 'zod'
import { API_KEY_PREFIX } from '@/configs/api'
import { actionClient } from '@/core/server/actions/client'
import { returnServerError } from '@/core/server/actions/utils'
import { setApiKeyCookie, validateApiKey } from '@/core/server/auth'

const SetApiKeySchema = z.object({
  apiKey: z
    .string()
    .trim()
    .min(1, 'API key is required')
    .startsWith(API_KEY_PREFIX, `API keys start with "${API_KEY_PREFIX}"`),
  destination: z.string().startsWith('/').default('/sandboxes'),
})

export const setApiKeyAction = actionClient
  .schema(SetApiKeySchema)
  .metadata({ actionName: 'setApiKey' })
  .action(async ({ parsedInput }) => {
    const { apiKey, destination } = parsedInput

    const result = await validateApiKey(apiKey)

    if (!result.valid) {
      if (result.reason === 'unauthorized') {
        return returnServerError('Invalid API key')
      }
      return returnServerError(
        'Could not reach the E2B API to validate the key. Please try again.'
      )
    }

    await setApiKeyCookie(apiKey)

    redirect(destination)
  })

'use server'

import { z } from 'zod'
import { apiKeyHeaders } from '@/configs/api'
import { authActionClient } from '@/core/server/actions/client'
import { returnServerError } from '@/core/server/actions/utils'
import { infra } from '@/core/shared/clients/api'
import { l } from '@/core/shared/clients/logger/logger'

const KillSandboxSchema = z.object({
  sandboxId: z.string().min(1, 'Sandbox ID is required'),
})

export const killSandboxAction = authActionClient
  .schema(KillSandboxSchema)
  .metadata({ actionName: 'killSandbox' })
  .action(async ({ parsedInput, ctx }) => {
    const { sandboxId } = parsedInput
    const { apiKey } = ctx

    const res = await infra.DELETE('/sandboxes/{sandboxID}', {
      headers: {
        ...apiKeyHeaders(apiKey),
      },
      params: {
        path: {
          sandboxID: sandboxId,
        },
      },
    })

    if (res.error) {
      const status = res.response.status

      l.error(
        {
          key: 'kill_sandbox_action:infra_error',
          error: res.error,
          sandbox_id: sandboxId,
          context: {
            status,
          },
        },
        `Failed to kill sandbox: ${res.error.message}`
      )

      if (status === 404) {
        return returnServerError('Sandbox not found')
      }

      return returnServerError('Failed to kill sandbox')
    }
  })

import { getPublicErrorMessage } from '@/core/shared/errors'

type ActionErrorOptions = {
  cause?: unknown
  expected?: boolean
}

export class ActionError extends Error {
  public expected: boolean
  public override cause?: unknown

  constructor(message: string, options: ActionErrorOptions = {}) {
    super(message)
    this.name = 'ActionError'
    this.expected = options.expected ?? true
    this.cause = options.cause
  }
}

export const returnServerError = (
  message: string,
  options?: ActionErrorOptions
) => {
  throw new ActionError(message, options)
}

export function handleDefaultInfraError(
  status: number,
  cause?: unknown
): never {
  return returnServerError(getPublicErrorMessage({ status }), {
    cause,
    expected: status < 500,
  })
}

export const flattenClientInputValue = (
  clientInput: unknown,
  key: string
): string | undefined => {
  if (typeof clientInput === 'object' && clientInput && key in clientInput) {
    return clientInput[key as keyof typeof clientInput]
  }

  return undefined
}

const SAFE_INPUT_KEYS = new Set<string>([
  'templateId',
  'sandboxId',
  'userId',
  'webhookId',
  'organizationId',
  'page',
  'pageSize',
  'limit',
  'offset',
  'sortBy',
  'sortOrder',
  'mode',
  'kind',
  'type',
])

function describeValue(value: unknown): string {
  if (value === null) return 'null'
  if (value === undefined) return 'undefined'
  if (Array.isArray(value)) return `array(${value.length})`
  const t = typeof value
  if (t === 'string') return `string(${(value as string).length})`
  if (t === 'object') return 'object'
  return t
}

/**
 * Sanitize action `clientInput` for safe logging (e.g. telemetry summaries).
 *
 * - Allowlisted scalar keys are inlined as-is.
 * - Everything else is replaced with `_<key>: <type-hint>` so shape and
 *   length are visible without leaking values.
 *
 * Allowlist-based sanitization is the inverse of the old blocklist-via-pino-
 * redaction approach: new sensitive fields are safe by default and only become
 * loggable when explicitly added to {@link SAFE_INPUT_KEYS}.
 */
export function sanitizeClientInput(input: unknown): Record<string, unknown> {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { _shape: describeValue(input) }
  }

  const out: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(input as Record<string, unknown>)) {
    const valueType = typeof value
    if (
      SAFE_INPUT_KEYS.has(key) &&
      (valueType === 'string' ||
        valueType === 'number' ||
        valueType === 'boolean')
    ) {
      out[key] = value
    } else {
      out[`_${key}`] = describeValue(value)
    }
  }
  return out
}
